.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
.chat-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d23;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #2d3039;
}

.sidebar-header {
    padding: 16px 20px;
    border-bottom: 1px solid #2d3039;
}

.sidebar-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 10px 20px;
    cursor: pointer;
    position: relative;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #2d3039;
}

.channel-item.active {
    background: #3b4048;
    border-left: 3px solid #4a9eff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: #e0e0e0;
}

.channel-description {
    font-size: 0.75rem;
    color: #888;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 16px;
    top: 50%;
    transform: translateY(-50%);
    background: #4a9eff;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 7px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main Area */
.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #23262d;
    min-width: 0;
}

.chat-main.thread-open {
    max-width: 55%;
}

.main-header {
    padding: 14px 24px;
    border-bottom: 1px solid #2d3039;
    background: #1e2128;
}

.main-header h2 {
    margin: 0;
    color: #fff;
    font-size: 1.15rem;
}

.main-header p {
    margin: 4px 0 0;
    color: #888;
    font-size: 0.85rem;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 24px;
}

.loading-indicator {
    text-align: center;
    color: #888;
    padding: 12px;
    font-size: 0.85rem;
}

.message-item {
    padding: 10px 14px;
    border-radius: 6px;
    position: relative;
    margin-bottom: 4px;
    transition: background 0.1s;
}

.message-item:hover {
    background: #2a2d35;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 10px;
    margin-bottom: 4px;
}

.message-author {
    font-weight: 700;
    color: #e0e0e0;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.75rem;
    color: #666;
}

.message-content {
    color: #ccc;
    font-size: 0.9rem;
    line-height: 1.45;
    word-wrap: break-word;
}

.message-reactions {
    display: flex;
    gap: 6px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2d3039;
    border: 1px solid #3b4048;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #ccc;
