}

.reaction-badge:hover {
    background: #3b4048;
    border-color: #4a9eff;
}

.thread-link {
    margin-top: 6px;
    font-size: 0.8rem;
    color: #4a9eff;
    cursor: pointer;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: 4px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #2a2d35;
    border: 1px solid #3b4048;
    border-radius: 6px;
    padding: 2px 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
