.action-btn {
    background: none;
    border: none;
    color: #aaa;
    font-size: 0.78rem;
    padding: 4px 8px;
    border-radius: 4px;
    cursor: pointer;
    white-space: nowrap;
}

.action-btn:hover {
    background: #3b4048;
    color: #fff;
}

.emoji-picker-container {
    position: relative;
}

