    padding: 4px 6px;
    border-radius: 4px;
    transition: background 0.1s;
}

.emoji-option:hover {
    background: #3b4048;
}

/* Message Input */
.message-input-area {
    padding: 12px 24px;
    border-top: 1px solid #2d3039;
    display: flex;
    gap: 10px;
    align-items: flex-end;
    background: #1e2128;
}

.message-input-area textarea {
    flex: 1;
    resize: none;
    background: #2a2d35;
    border: 1px solid #3b4048;
    border-radius: 8px;
    padding: 10px 14px;
    color: #e0e0e0;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input-area textarea:focus {
    border-color: #4a9eff;
}

.message-input-area textarea::placeholder {
    color: #666;
}

.send-btn {
    background: #4a9eff;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #3a8eef;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

